import java.util.*;
public class MapBench {
 static final int R=15,C=14; static final int[] d={0,1,0,-1,0}; static long calls,deadline; static class Timeout extends RuntimeException {}
 static boolean dfs(int[][] g,int x,int y) { if((++calls & 4095)==0 && System.nanoTime()>deadline) throw new Timeout(); if(x==1&&y==C-2)return true; g[x][y]=1; for(int i=0;i<4;i++){int a=x+d[i],b=y+d[i+1]; if(a>=0&&a<R&&b>=0&&b<C&&g[a][b]==0&&dfs(g,a,b)){g[x][y]=0;return true;}} g[x][y]=0;return false; }
 static boolean bfs(int[][] g){boolean[][] seen=new boolean[R][C]; ArrayDeque<int[]> q=new ArrayDeque<>(); seen[R-2][1]=true;q.add(new int[]{R-2,1});while(!q.isEmpty()){int[] p=q.poll();if(p[0]==1&&p[1]==C-2)return true;for(int i=0;i<4;i++){int x=p[0]+d[i],y=p[1]+d[i+1];if(x>=0&&x<R&&y>=0&&y<C&&g[x][y]==0&&!seen[x][y]){seen[x][y]=true;q.add(new int[]{x,y});}}}return false;}
 static int[][] map(Random rnd){int[][] g=new int[R][C];for(int x=0;x<R;x++)for(int y=0;y<C;y++)if(x==0||x==R-1||y==0||y==C-1)g[x][y]=1;for(int i=0;i<10;i++)for(int j=0;j<1000;j++){int x=rnd.nextInt(R),y=rnd.nextInt(C);if(g[x][y]==1||g[R-1-x][C-1-y]==1||(x==R-2&&y==1)||(x==1&&y==C-2))continue;g[x][y]=g[R-1-x][C-1-y]=1;break;}return g;}
 static String stats(List<Long> v){Collections.sort(v);return String.format(Locale.US,"n=%d median=%.3f ms p95=%.3f ms max=%.3f ms",v.size(),v.get(v.size()/2)/1e6,v.get((int)Math.ceil(v.size()*.95)-1)/1e6,v.get(v.size()-1)/1e6);}
 public static void main(String[] args){Random r=new Random(20261026);for(int i=0;i<1000;i++)bfs(map(r));r=new Random(20261026);List<Long> b=new ArrayList<>(),f=new ArrayList<>();int timeout=0,unreachable=0,mismatch=0;for(int i=0;i<200;i++){int[][] g=map(r);long t=System.nanoTime();boolean expected=bfs(g);b.add(System.nanoTime()-t);if(!expected)unreachable++;calls=0;deadline=System.nanoTime()+100_000_000L;t=System.nanoTime();try {boolean got=dfs(g,R-2,1);f.add(System.nanoTime()-t);if(got!=expected)mismatch++;}catch(Timeout ex){timeout++;}}System.out.println("seed=20261026 maps=200 DFS timeout=100ms unreachable="+unreachable+" mismatches="+mismatch+" timeouts="+timeout);System.out.println("BFS "+stats(b));System.out.println("DFS completed only "+stats(f));}
}
